s='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda c: sum(r.count(c) for r in grid))
    seen=set()
    fill_map={1:7, 3:2, 5:7, 6:7, 9:7}
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                x,y=stack.pop(); comp.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and grid[nx][ny]==color and (nx,ny) not in seen:
                        seen.add((nx,ny)); stack.append((nx,ny))
            r0=min(x for x,y in comp); r1=max(x for x,y in comp)
            c0=min(y for x,y in comp); c1=max(y for x,y in comp)
            if r1-r0>=2 and c1-c0>=2 and all(grid[x][y]==color for x in (r0,r1) for y in range(c0,c1+1)) and all(grid[x][y]==color for y in (c0,c1) for x in range(r0,r1+1)):
                fill=fill_map.get(color,7)
                for x in range(r0+1,r1):
                    for y in range(c0+1,c1):
                        if grid[x][y]==bg: out[x][y]=fill
    return out
'''
